INSERT INTO `pre_orders` (`id`, `title`, `title_en`, `second_title`, `slug`, `sub_title`, `author`, `author_en`, `description`, `description_2`, `price`, `discount_price`, `release_date`, `cover_image`, `second_cover_image`, `status`, `is_hot_deal`, `created_at`, `updated_at`, `free_delivery`) VALUES
(11, 'হৃদ-প্রদীপ', 'Heart Lamp and a person who is no one', 'একজন কেউ না ', 'heart-lamp-and-a-person-who-is-no-one', 'হৃদ-প্রদীপ বইটি প্রি-অর্ডার করলেই, সাথে পাচ্ছেন \'একজন কেউ না\' বইটি এবং মোট মূল্যে ২০% ছাড়', 'জাভেদ ইকবাল', '', 'হার্ট ল্যাম্প\r\nমুখোমুখি বসবার বই\r\n\r\nভারতীয় কন্নড় ভাষার লেখিকা বানু মুস্তাকের গল্প সংকলন ‘এদেয়া হালোতে’, যার ইংরেজি অনুবাদ ‘হার্ট ল্যাম্প’ ২০২৫ সালে ইন্টারন্যাশনাল বুকার প্রাইজে ভূষিত হয়েছে। এই পুরস্কারের মাধ্যমে ইন্টারন্যাশনাল বুকারের দুই দশকের একটি ধারার অবসান ঘটেছে। কেননা, ইন্টারন্যাশনাল বুকারের ইতিহাসে এই প্রথমবারের মতো কোনো ছোটগল্প সংকলনকে পুরস্কৃত করা হলো। বলা যায়, বানু মুস্তাকের অনবদ্য লেখা কমিটিকে তাকে পুরস্কার দিতে ‘বাধ্য’ করেছে।\r\n\r\nপুরস্কার কমিটির সভাপতি ম্যাক্স পিটার সংকলনটির প্রশংসা করে বলেন, ‘সংকলনের গল্পগুলো জীবনবোধে ভরপুর, গভীরভাবে রাজনৈতিক, এবং আরো গভীরভাবে মানবীয়তায় পরিপূর্ণ। এর গল্পগুলো প্রজনন অধিকার, বর্ণগত অবিচার এবং আত্মার যন্ত্রণার মতো বিষয়গুলোর সাথে নিরন্তর সংগ্রাম চালিয়ে যায়; তবুও একটা মুহূর্তের জন্যও গল্পগুলোর সাহিত্যিক সৌন্দর্যের সাথে আপোষ করে না। এটি এখন ইংরেজি পাঠকদের জন্য প্রকৃত অর্থেই একটি নতুন বই।’\r\n\r\nবানুর বারোটি গল্প তার সময় ও সমাজের সাক্ষ্য। তার লেখায় পুরুষতান্ত্রিকতা, নারীবাদ, ধর্ম, বর্ণ, শ্রেণি এবং লিঙ্গের মতো বিষয়গুলো সহজ, আয়াসহীনভাবে ফুটে উঠেছে। কোনোপ্রকার স্লোগানবাজি নেই, বড় বড় কথা-নীতিকথা নেই; কেবল গল্প বলে গিয়েছেন। গল্পগুলো যদিও মুসলিম সামাজিক কাঠামোর মধ্যে স্থাপিত, কিন্তু এগুলো কেবল মুসলিম নারীদেরই গল্প নয়, হয়ে উঠেছে প্রতিটি নারীর গল্প। গল্পগুলো পড়তে পড়তে, যারা ইসমত চুঘতাই কিংবা রশিদ জাহানের গল্পের সাথে পরিচিত, তাদের এই দুই মহীয়সী উর্দু লেখিকার কথা মনে আসতে পারে। হার্ট ল্যাম্প তাই শুধু পড়বার বই-ই নয়, মুখোমুখি বসবারও বই।', 'জীবন থেকে গল্প নিয়ে সিনেমা তৈরি হয়, কিন্তু গল্প থেকে চেষ্টা করেও কেউ সেরকম একটি জীবন তৈরি করতে পারে না- এটা আমার একটি ভাবনা। ছোটবেলায় গোগ্রাসে যে কবির কবিতা পড়তাম তিনি একসময় লিখেছেন, \"যেমন ইচ্ছে লেখার আমার কবিতার খাতা\"। অর্থাৎ ইচ্ছেমতো হয়তো কিছুই হয় না। আমার ক্ষেত্রেও তাই, জীবন আমি ফ্রেমে করে বাঁধিনি, আমার সঞ্চয় ধূসর, কুয়াশা। আমি ফুটতে ফুটতে, ঝরতে ঝরতে আজ এ বেলায় এসেছি।\r\n\r\nআমার হারানো সবকিছু রয়ে গেছে আজিমপুরের সবুজ ঘাসে, কলোনির চিলেকোঠায়। পুরান ঢাকায় কেটে যাওয়া ঘুড়ি ধরতে যে পথ ধরে ছুটতাম, সেখানে পায়ের দাগ ছিলো অনেকদিন। আমি তা ধরে রাখিনি। কোনো নাম, রঙিন মার্বেল, লাটাই সুতো, কোনো ফুল, কোনো মালা আমি নিজের কাছে রেখে দেইনি। পাড়ার বোনদের আদরের ডাক তখন বুঝতেও পারিনি। জীবনকে ছড়াতে ছড়াতে আমি এখানে এসেছি, কখনও ফিরিনি ফেলে আসা পথে... সেখানেই পড়ে আছে আমার ইচ্ছে জীবন অনুভূতি- হাসি আর অশ্রুবিন্দু।\r\n\r\nজীবনের পাঁচ দশকেরও বেশি পথ নেহাত কম সময় নয়। দীর্ঘ এই সময়ে জমে থাকা বিন্দু বিন্দু জল কিংবা জলছবির একটি গ্রন্থিত রূপ একজন কেউ না।\r\n\r\nলেখক - রুমি নোমান', 1200.00, 960.00, '2026-05-30', 'po_69edd764a9ef9.webp', 'po2_69edd764aa18b.webp', 'Open', 1, '2026-03-15 09:19:35', '2026-04-26 09:46:40', 1);
